<section class="admin-v2-page-intro"><div><span class="admin-v2-eyebrow">ARABIC TRANSLATION</span><h2>الأعمال بانتظار الترجمة العربية</h2><p>يعرض هذا الطابور الأعمال غير العربية المعتمدة تحريرياً. الاعتماد لا ينشر العمل؛ النشر يبقى محجوباً إلى أن تعتمد النسخة العربية.</p></div></section>
<section class="admin-v2-table-panel"><div class="admin-v2-panel-head"><h3>الطابور الفعلي</h3><span><?=e(count($rows))?></span></div><div class="admin-v2-responsive-table"><table class="admin-v2-table"><thead><tr><th>العمل</th><th>الكاتب</th><th>اللغة الأصلية</th><th>حالة العربية</th><th>التعيين</th><th>إجراءات</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="6"><div class="admin-v2-empty">لا توجد أعمال معتمدة بانتظار ترجمة عربية.</div></td></tr><?php else:foreach($rows as $row):?><tr><td><strong><?=e($row['original_title']?:'بدون عنوان')?></strong><small>#<?=e($row['id'])?> · النص الأصلي: <?=e($row['original_review'])?></small></td><td><?=e($row['author_name'])?><small>@<?=e($row['username'])?></small></td><td><?=e(language_flag($row['original_locale']).' '.language_name($row['original_locale']))?></td><td><span class="admin-v2-badge <?=e($row['arabic_status']??'draft')?>"><?=e(($row['arabic_status']??'غير موجود').' / '.($row['arabic_review']??'مسودة'))?></span></td><td><small>المترجم: <?=e($row['translator_name']??'غير معيّن')?></small><small>المراجع: <?=e($row['reviewer_name']??'غير معيّن')?></small><small>المهمة: <?=e($row['assignment_status']??'queued')?></small></td><td class="admin-v2-inline-actions"><a class="admin-v2-button" href="/writer/articles/<?=e($row['id'])?>">فتح العمل</a><details><summary class="admin-v2-button">تعيين</summary><form method="post" action="/admin-v2/translations/assign" class="admin-v2-actions"><input type="hidden" name="article_id" value="<?=e($row['id'])?>"><?=csrf_field()?><label>المترجم<select name="translator_id"><option value="">غير معيّن</option><?php foreach($staff as $member):?><option value="<?=e($member['id'])?>" <?=($row['translator_name']??'')===$member['name']?'selected':''?>><?=e($member['name'].' @'.$member['username'])?></option><?php endforeach;?></select></label><label>المراجع<select name="reviewer_id"><option value="">غير معيّن</option><?php foreach($staff as $member):?><option value="<?=e($member['id'])?>" <?=($row['reviewer_name']??'')===$member['name']?'selected':''?>><?=e($member['name'].' @'.$member['username'])?></option><?php endforeach;?></select></label><label>حالة المهمة<select name="assignment_status"><?php foreach(['queued'=>'بانتظار البدء','in_progress'=>'قيد الترجمة','review'=>'بانتظار المراجعة','approved'=>'مكتملة ومعتمدة','cancelled'=>'ملغاة'] as $key=>$label):?><option value="<?=e($key)?>" <?=($row['assignment_status']??'queued')===$key?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></label><label>ملاحظة<textarea name="notes" rows="2" maxlength="2000"><?=e($row['assignment_notes']??'')?></textarea></label><button class="admin-v2-button primary" type="submit">حفظ التعيين</button></form></details></td></tr><?php endforeach;endif;?></tbody></table></div></section>
